let session=null,state={data:{},users:[],settings:{},allowed:[]},route='dashboard',query='',filter='',view='table',period=today().slice(0,7),reportStart=today().slice(0,7)+'-01',reportEnd=today(),lastFocus=null;
const list=e=>state.data[e]||[];
const lookup=(entity,id)=>entity==='users'?state.users.find(x=>x.id===id)?.name||'—':list(entity).find(x=>x.id===id)?.name||'—';
const sum=(arr,key)=>arr.reduce((s,r)=>s+Number(r[key]||0),0);
const roleLabel={admin:'Administrador',finance:'Financeiro',sales:'Comercial',production:'Produção'};
async function api(path,method='GET',data){const response=await fetch('/api'+path,{method,headers:{'Content-Type':'application/json',...(session?.csrf?{'X-CSRF-Token':session.csrf}:{})},...(data!==undefined?{body:JSON.stringify(data)}:{})});const raw=await response.text();let result;try{result=JSON.parse(raw);}catch{throw Error(response.status===404?'A API não foi encontrada. Publique a pasta api e vercel.json e confira a pasta raiz do projeto na Vercel.':'O servidor retornou uma resposta inválida (HTTP '+response.status+'). Confira os logs da publicação na Vercel.');}if(!response.ok){if(response.status===401&&session?.user){session=null;await boot();}throw Error(result.error||'Falha na operação.');}return result;}
function toast(msg,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=msg;$('#toasts').append(el);setTimeout(()=>el.remove(),6000);}
function brand(){return `<div class="brand">${state.settings.logo?`<img src="${esc(state.settings.logo)}" alt="Logo">`:'<b class="brand-mark">P</b>'}<div>PRATES DIGITAL<span>WORKSPACE</span></div></div>`;}
async function boot(){try{session=await api('/session');if(!session.user)return authScreen(session.setup?'setup':'login');await reload();route=location.hash.slice(1)||'dashboard';shell();}catch(e){$('#app').innerHTML=`<div class="loading">Não foi possível conectar<p>${esc(e.message)}</p><button id="retry">Tentar novamente</button></div>`;$('#retry').onclick=boot;}}
async function reload(){state=await api('/state');}
function authScreen(mode){const setup=mode==='setup',recover=mode==='recover';$('#app').innerHTML=`<div class="auth"><section class="auth-story">${brand()}<div><div class="eyebrow">Seu próximo nível começa aqui</div><h1>Menos tarefas soltas.<br>Mais <em>resultados.</em></h1><p>Clientes, projetos e números. Tudo conectado para Joaquim e Kauã construírem a Prates Digital.</p></div><div class="auth-foot">PRATES DIGITAL © ${new Date().getFullYear()} · Gestão de serviços digitais</div></section><section class="auth-form-wrap"><form class="auth-form" id="auth-form"><div class="eyebrow">Administrativo</div><h2>${setup?'Crie seu primeiro acesso':recover?'Recupere seu acesso':'Bom ter você por aqui.'}</h2><p>${setup?'Você será o primeiro administrador. Depois, cadastre o outro sócio em Equipe e acessos.':recover?'Use o código de recuperação guardado ao criar sua conta.':'Entre na sua conta para acompanhar a operação.'}</p>${setup&&session?.setupKeyRequired?'<label>Chave de instalação<input name="setup_key" type="password" required autocomplete="off" placeholder="A PRATES_SETUP_KEY definida na Vercel"></label>':''}${setup?'<label>Seu nome<input name="name" required autocomplete="name" placeholder="Joaquim ou Kauã"></label>':''}<label>E-mail<input name="email" type="email" required autocomplete="username" placeholder="voce@empresa.com"></label>${recover?'<label>Código de recuperação<input name="code" required autocomplete="off"></label>':''}<label>${recover?'Nova senha':'Senha'}<input name="password" type="password" required ${setup||recover?'minlength="10"':''} autocomplete="${setup||recover?'new-password':'current-password'}" placeholder="${setup||recover?'Pelo menos 10 caracteres':'Sua senha'}"></label><div id="auth-error"></div><button class="primary" type="submit">${setup?'Criar conta':recover?'Recuperar acesso':'Entrar no workspace'} ${icon('arrow')}</button>${!setup?`<button class="link" id="auth-switch" type="button">${recover?'Voltar ao login':'Esqueci minha senha'}</button>`:''}<small>Acesso restrito à equipe da Prates Digital.</small></form></section></div>`;
$('#auth-switch')?.addEventListener('click',()=>authScreen(recover?'login':'recover'));$('#auth-form').onsubmit=async e=>{e.preventDefault();const button=$('button[type=submit]',e.target);button.disabled=true;try{const r=await api('/'+(setup?'setup':recover?'recover':'login'),'POST',Object.fromEntries(new FormData(e.target)));await boot();if(r.recovery)showRecovery(r.recovery);}catch(err){$('#auth-error').innerHTML=`<div class="form-error">${esc(err.message)}</div>`;}finally{button.disabled=false;}};}
function shell(){if(!canRoute(route))route='dashboard';$('#app').innerHTML=`<aside class="sidebar">${brand()}<div class="workspace-label"><b>PD</b><div>Prates Digital<small>Espaço administrativo</small></div></div><nav class="nav">${GROUPS.map(([group,items])=>{const entries=items.map(item=>typeof item==='string'?[item,SC[item].title,SC[item].icon]:item).filter(([id])=>canRoute(id));return entries.length?`<div class="nav-title">${group}</div>${entries.map(([id,title,ic])=>`<a href="#${id}" data-route="${id}" class="${route===id?'active':''}">${icon(ic)}${esc(title)}</a>`).join('')}`:'';}).join('')}</nav><div class="sidebar-footer"><div class="avatar">${esc(session.user.name.charAt(0))}</div><div>${esc(session.user.name)}<small>${roleLabel[session.user.role]}</small></div><button class="icon-button ghost" id="logout" title="Sair">${icon('logout')}</button></div></aside><div class="main"><header class="topbar"><button class="menu-toggle icon-button" id="menu" aria-label="Abrir menu">${icon('menu')}</button><div class="breadcrumb">Workspace <span>/ <b id="crumb"></b></span></div><form class="global-search" id="search-form">${icon('search')}<input id="global-search" aria-label="Buscar em todos os registros" placeholder="Buscar no workspace…"></form><span class="day">${new Date().toLocaleDateString('pt-BR',{day:'numeric',month:'short',year:'numeric'})}</span><button class="icon-button ghost" id="notifications" title="Alertas de prazos">${icon('bell')}</button><div class="avatar">${esc(session.user.name.charAt(0))}</div></header><main class="content" id="content"></main></div>`;
$('#menu').onclick=()=>$('.sidebar').classList.toggle('open');$('#logout').onclick=async()=>{await api('/logout','POST',{});session=null;boot();};$('#notifications').onclick=notifications;$('#search-form').onsubmit=e=>{e.preventDefault();globalSearch($('#global-search').value);};render();}
function canRoute(r){if(SC[r])return state.allowed.includes(r);if(['settings','users','audit'].includes(r))return session.user.role==='admin';if(['balance','reports'].includes(r))return state.allowed.includes('receivables');return r==='dashboard';}
window.addEventListener('hashchange',()=>{if(!session?.user)return;route=location.hash.slice(1)||'dashboard';query='';filter='';view=SC[route]?.board?'board':'table';if(!canRoute(route))route='dashboard';$$('[data-route]').forEach(a=>a.classList.toggle('active',a.dataset.route===route));$('.sidebar')?.classList.remove('open');render();});
function title(){return SC[route]?.title||({dashboard:'Dashboard',balance:'Balanço gerencial',reports:'Relatórios',users:'Equipe e acessos',audit:'Histórico de alterações',settings:'Configurações'})[route];}
function heading(t,desc,actions='',eyebrow='Prates Digital'){return `<div class="page-heading"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(t)}</h1><p>${esc(desc)}</p></div><div class="heading-actions">${actions}</div></div>`;}
function render(){if(!$('#content'))return;$('#crumb').textContent=title();if(SC[route])return entityPage();({dashboard,balance:reports,reports,users:usersPage,audit:auditPage,settings:settingsPage})[route]?.();}
function badge(s){const good=['Ativo','Pago','Confirmada','Confirmado','Aprovada','Aprovado','Assinado','Concluída','Concluída','Completo','Finalizado','Publicado','Ganho'];const bad=['Cancelado','Cancelada','Perdido','Recusada','Atrasado','Urgente'];return `<span class="badge ${good.includes(s)?'green':bad.includes(s)?'red':['Em produção','Em andamento','Ativa'].includes(s)?'blue':'orange'}">${esc(s||'—')}</span>`;}
function financialStatus(r){return r.status==='Cancelado'?'Cancelado':Number(r.paid||0)>=Number(r.amount||0)?'Pago':r.due&&r.due<today()?'Atrasado':r.paid>0?'Parcial':'Pendente';}
function cell(e,r,key){const f=SC[e].fields.find(f=>f.key===key);if(['amount','paid','price','cost','budget','spend'].includes(key))return money(r[key]);if(key==='status')return badge(['receivables','expenses'].includes(e)?financialStatus(r):r[key]);if(['date','due','start','end','validUntil','nextDue'].includes(key))return dateFmt(r[key]);if(f?.type==='relation')return esc(lookup(f.options,r[key]));if(key==='target')return number(r[key]);return esc(r[key]||'—');}
function empty(t='Nenhum registro por aqui',desc='Comece pelo primeiro cadastro. Os dados salvos aparecerão aqui.',action=''){return `<div class="empty">${icon('brief')}<h3>${esc(t)}</h3><p>${esc(desc)}</p>${action}</div>`;}
function metric(label,value,sub,ic='wallet',accent=false){return `<div class="metric ${accent?'accent':''}"><div class="metric-head">${esc(label)}${icon(ic)}</div><div class="number">${esc(value)}</div><small>${esc(sub)}</small></div>`;}
function inRange(s,start,end){return s&&s.slice(0,10)>=start&&s.slice(0,10)<=end;}
function payments(e,start,end,media=false){return list(e).filter(r=>r.status!=='Cancelado'&&(media||r.category!=='Verba de mídia')).flatMap(r=>(r.payments||[]).filter(p=>inRange(p.date,start,end)).map(p=>({...p,category:r.category,client:r.client,owner:r.owner,name:r.name})));}
function financial(start,end){const incoming=sum(payments('receivables',start,end),'amount'),outgoing=sum(payments('expenses',start,end),'amount'),moves=list('partners').filter(r=>r.status!=='Cancelado'&&inRange(r.date,start,end));const contributions=sum(moves.filter(r=>r.kind==='Aporte'),'amount'),withdrawals=sum(moves.filter(r=>r.kind!=='Aporte'),'amount');return {incoming,outgoing,result:incoming-outgoing,contributions,withdrawals,net:incoming-outgoing+contributions-withdrawals};}
function goalValue(g){const start=g.start||'0000-01-01',end=g.end||'9999-12-31',owned=r=>!g.owner||r.owner===g.owner;switch(g.metric){case 'Valor de vendas':return sum(list('sales').filter(r=>r.status!=='Cancelado'&&inRange(r.date,start,end)&&owned(r)),'amount');case 'Quantidade de vendas':return list('sales').filter(r=>r.status!=='Cancelado'&&inRange(r.date,start,end)&&owned(r)).length;case 'Recebimentos':return sum(payments('receivables',start,end).filter(owned),'amount');case 'Novos clientes':return list('clients').filter(r=>inRange(r.created,start,end)&&owned(r)).length;case 'Entregas concluídas':return list('projects').filter(r=>r.status==='Finalizado'&&inRange(r.updated,start,end)&&owned(r)).length;default:return Number(g.current||0);}}
function goalCards(goals){return goals.length?goals.map(g=>{const actual=goalValue(g),percent=g.target>0?actual/g.target*100:0;return `<div class="mini-row"><div style="width:100%"><div style="display:flex;justify-content:space-between;gap:10px"><strong>${esc(g.name)}</strong><small>${number(percent)}%</small></div><div class="progress"><span style="width:${Math.min(100,Math.max(0,percent))}%"></span></div><small>${number(actual)} de ${number(g.target)} · ${esc(g.metric)}</small></div></div>`;}).join(''):empty('Defina a próxima conquista','Cadastre metas de vendas, recebimentos e entregas.','<a href="#goals"><button class="ghost">Definir uma meta</button></a>');}
function dashboard(){const start=period+'-01',end=period+'-31',fin=financial(start,end),sales=list('sales').filter(r=>r.status!=='Cancelado'&&inRange(r.date,start,end)),pending=list('receivables').filter(r=>r.status!=='Cancelado'),open=sum(pending,'amount')-sum(pending,'paid'),active=list('projects').filter(r=>r.status!=='Finalizado');const hasFinance=state.allowed.includes('receivables');$('#content').innerHTML=heading(`Visão geral`,`Olá, ${session.user.name.split(' ')[0]}. Veja como está a Prates Digital hoje.`,`<input type="month" id="period" value="${period}" aria-label="Mês do dashboard">${state.allowed.includes('sales')?`<button class="primary" data-new="sales">${icon('plus')} Nova venda</button>`:''}`,'Seu workspace')+`<div class="metrics">${hasFinance?metric('Recebido no mês',money(fin.incoming),'Recebimentos confirmados · sem verba de mídia','wallet',true)+metric('Vendas no mês',money(sum(sales,'amount')),sales.length+' vendas registradas','sales')+metric('Resultado de caixa',money(fin.result),'Recebimentos menos despesas pagas','chart')+metric('A receber',money(open),'Saldo em aberto · todos os períodos','clock'):metric('Projetos em andamento',active.length,'Projetos ainda não finalizados','project',true)+metric('Clientes',list('clients').length,'Clientes cadastrados','clients')+metric('Tarefas abertas',list('tasks').filter(x=>x.status!=='Concluída').length,'Compromissos da equipe','calendar')+metric('Conteúdos',list('content').length,'Publicações planejadas e entregues','file')}</div><div class="grid-main"><section class="panel"><div class="panel-head"><div><h2>${hasFinance?'Movimentação financeira':'Operação em andamento'}</h2><small>${hasFinance?'Recebimentos e pagamentos dos últimos 6 meses':'Organização dos projetos por etapa'}</small></div>${hasFinance?'<div class="chart-legend"><span><i class="dot"></i>Entradas</span><span><i class="dot gray"></i>Saídas</span></div>':''}</div><div class="panel-body">${hasFinance?chart():projectSummary()}</div></section><section class="panel"><div class="panel-head"><div><h2>Objetivos em foco</h2><small>Cada avanço conta.</small></div>${icon('target')}</div><div class="panel-body">${goalCards(list('goals').slice(0,3))}</div></section></div><div class="grid-main"><section class="panel"><div class="panel-head"><div><h2>${state.allowed.includes('sales')?'Últimas vendas':'Projetos recentes'}</h2><small>As movimentações mais recentes da equipe</small></div><a href="#${state.allowed.includes('sales')?'sales':'projects'}"><button class="ghost">Ver todos ${icon('arrow')}</button></a></div>${compactTable(state.allowed.includes('sales')?'sales':'projects',list(state.allowed.includes('sales')?'sales':'projects').slice(0,5))}</section><section class="panel"><div class="panel-head"><div><h2>Próximas entregas</h2><small>Prioridades que merecem atenção</small></div>${icon('calendar')}</div><div class="panel-body">${upcoming()}</div></section></div>`;$('#period').onchange=e=>{if(e.target.value){period=e.target.value;dashboard();}};bindCommon();}
function chart(){const months=Array.from({length:6},(_,i)=>{const d=new Date(period+'-15T12:00:00');d.setMonth(d.getMonth()-5+i);const m=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`,f=financial(m+'-01',m+'-31');return {...f,label:d.toLocaleDateString('pt-BR',{month:'short'})};});const max=Math.max(1,...months.flatMap(m=>[m.incoming,m.outgoing]));return `<svg class="chart" viewBox="0 0 620 220" role="img" aria-label="Gráfico de entradas e saídas nos últimos seis meses">${[0,1,2,3].map(i=>`<line x1="48" y1="${20+i*50}" x2="610" y2="${20+i*50}" stroke="#262628" stroke-dasharray="3 5"/><text x="0" y="${24+i*50}">${number(max*(3-i)/3)}</text>`).join('')}${months.map((m,i)=>{const x=76+i*89;return `<rect x="${x}" y="${170-m.incoming/max*150}" width="22" height="${Math.max(1,m.incoming/max*150)}" rx="4" fill="#ff743d"><title>${m.label}: ${money(m.incoming)} recebidos</title></rect><rect x="${x+28}" y="${170-m.outgoing/max*150}" width="22" height="${Math.max(1,m.outgoing/max*150)}" rx="4" fill="#66666c"><title>${m.label}: ${money(m.outgoing)} pagos</title></rect><text x="${x+8}" y="198">${esc(m.label)}</text>`;}).join('')}</svg>`;}
function projectSummary(){return ['Onboarding','Em produção','Aguardando cliente','Finalizado'].map(s=>`<div class="mini-row"><strong>${s}</strong>${badge(list('projects').filter(p=>p.status===s).length+' projetos')}</div>`).join('');}
function upcoming(){const rows=[...list('tasks').filter(r=>r.status!=='Concluída').map(r=>({...r,e:'tasks'})),...list('projects').filter(r=>r.status!=='Finalizado').map(r=>({...r,e:'projects'}))].filter(r=>r.due).sort((a,b)=>a.due.localeCompare(b.due)).slice(0,5);return rows.length?rows.map(r=>`<div class="mini-row"><div><strong>${esc(r.name)}</strong><small>${esc(lookup('users',r.owner))}</small></div><span class="badge ${r.due<today()?'red':''}">${dateFmt(r.due)}</span></div>`).join(''):empty('Agenda livre','As próximas tarefas e entregas com prazo aparecerão aqui.');}
function compactTable(e,rows){return rows.length?`<div class="table-wrap"><table class="table"><thead><tr>${SC[e].cols.slice(0,4).map(k=>`<th>${esc(SC[e].fields.find(f=>f.key===k)?.label||k)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${SC[e].cols.slice(0,4).map(k=>`<td>${cell(e,r,k)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:empty('Seu histórico começa aqui','Os dados são reais: nenhuma venda ou cliente fictício foi incluído.');}
function getFiltered(){return list(route).filter(r=>(!query||JSON.stringify(r).toLocaleLowerCase('pt-BR').includes(query.toLocaleLowerCase('pt-BR'))||lookup('clients',r.client).toLowerCase().includes(query.toLowerCase()))&&(!filter||(route==='receivables'||route==='expenses'?financialStatus(r):r.status)===filter));}
function entityPage(){const sc=SC[route],rows=getFiltered(),statuses=['receivables','expenses'].includes(route)?['Pendente','Parcial','Pago','Atrasado','Cancelado']:sc.fields.find(f=>f.key==='status')?.options||[];$('#content').innerHTML=heading(sc.title,sc.desc,`<button id="export">${icon('download')} Exportar</button><button class="primary" data-new="${route}">${icon('plus')} ${route==='sales'?'Nova venda':'Novo cadastro'}</button>`)+`<div class="toolbar"><div class="toolbar-left"><input id="filter-search" placeholder="Buscar ${sc.title.toLowerCase()}…" aria-label="Buscar registros" value="${esc(query)}">${statuses.length?`<select id="status-filter" aria-label="Filtrar situação"><option value="">Todas as situações</option>${statuses.map(s=>`<option ${s===filter?'selected':''}>${esc(s)}</option>`).join('')}</select>`:''}</div><div class="toolbar-right">${sc.board?`<button data-view="board" class="${view==='board'?'primary':''}">${icon('project')} Quadro</button><button data-view="table" class="${view==='table'?'primary':''}">Lista</button>`:''}${['content','tasks'].includes(route)?`<button data-view="calendar" class="${view==='calendar'?'primary':''}">${icon('calendar')} Calendário</button><button data-view="table">Lista</button>`:''}<small>${rows.length} registros</small></div></div>${route==='goals'&&rows.length?`<div class="panel" style="padding:10px 22px;margin-bottom:20px">${goalCards(rows)}</div>`:''}${view==='board'&&sc.board?board(rows):view==='calendar'?calendar(rows):tablePage(rows)}`;$('#filter-search').oninput=e=>{query=e.target.value;const start=e.target.selectionStart;entityPage();$('#filter-search').focus();$('#filter-search').setSelectionRange(start,start);};$('#status-filter')?.addEventListener('change',e=>{filter=e.target.value;entityPage();});$('#export').onclick=()=>exportCSV(route,rows);$$('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;entityPage();});bindCommon();$$('[data-drag]').forEach(el=>el.ondragstart=e=>e.dataTransfer.setData('text/plain',el.dataset.drag));$$('[data-drop]').forEach(el=>{el.ondragover=e=>{e.preventDefault();el.classList.add('over');};el.ondragleave=()=>el.classList.remove('over');el.ondrop=async e=>{e.preventDefault();const r=list(route).find(r=>r.id===e.dataTransfer.getData('text/plain'));if(r)await mutateRecord(route,r,{status:el.dataset.drop});};});$('#calendar-month')?.addEventListener('change',e=>{period=e.target.value;entityPage();});}
function tablePage(rows){const sc=SC[route];return `<section class="panel">${rows.length?`<div class="table-wrap"><table class="table"><thead><tr>${sc.cols.map(k=>`<th>${esc(k==='paid'?'Pago':sc.fields.find(f=>f.key===k)?.label||k)}</th>`).join('')}<th>Ações</th></tr></thead><tbody>${rows.map(r=>`<tr>${sc.cols.map(k=>`<td>${cell(route,r,k)}</td>`).join('')}<td><div class="actions"><button data-detail="${r.id}">Abrir</button><button data-edit="${r.id}" aria-label="Editar ${esc(r.name)}">Editar</button></div></td></tr>`).join('')}</tbody></table></div>`:empty(query||filter?'Nenhum resultado':'Nenhum cadastro ainda',query||filter?'Experimente outros filtros.':'Adicione o primeiro registro para organizar esta área.',`<button data-new="${route}" class="primary">${icon('plus')} Novo cadastro</button>`)}<div class="table-bottom"><span>${rows.length} registros encontrados</span><span>Prates Digital · Dados salvos no servidor</span></div></section>`;}
function board(rows){return `<div class="kanban">${SC[route].fields.find(f=>f.key==='status').options.map(s=>{const items=rows.filter(r=>r.status===s);return `<section class="kanban-column" data-drop="${esc(s)}"><div class="kanban-title">${esc(s)}<span>${items.length}</span></div>${items.map(r=>`<article class="kanban-card" draggable="true" data-drag="${r.id}" data-detail="${r.id}" tabindex="0"><h3>${esc(r.name)}</h3><p>${esc(lookup('clients',r.client))}</p><footer><span>${esc(lookup('users',r.owner))}</span><span>${r.amount?money(r.amount):dateFmt(r.due)}</span></footer></article>`).join('')}${!items.length?'<small>Arraste um cartão para cá</small>':''}</section>`;}).join('')}</div><small>No celular, abra o registro e altere a situação em Editar.</small>`;}
function calendar(rows){const [y,m]=period.split('-').map(Number),first=new Date(y,m-1,1),days=new Date(y,m,0).getDate(),offset=(first.getDay()+6)%7;return `<div style="margin-bottom:15px;max-width:200px"><input id="calendar-month" type="month" value="${period}" aria-label="Mês do calendário"></div><div class="calendar">${['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'].map(d=>`<div class="calendar-week">${d}</div>`).join('')}${Array.from({length:offset},()=>'<div class="calendar-day"></div>').join('')}${Array.from({length:days},(_,i)=>{const d=period+'-'+String(i+1).padStart(2,'0');return `<div class="calendar-day ${d===today()?'today':''}"><small>${i+1}</small>${rows.filter(r=>(route==='tasks'?r.due:r.date)===d).map(r=>`<button data-detail="${r.id}" title="${esc(r.name)}">${esc(r.name)}</button>`).join('')}</div>`;}).join('')}</div>`;}
function bindCommon(){$$('[data-new]').forEach(b=>b.onclick=()=>editForm(b.dataset.new));$$('[data-edit]').forEach(b=>b.onclick=()=>editForm(route,list(route).find(r=>r.id===b.dataset.edit)));$$('[data-detail]').forEach(b=>{b.onclick=()=>detail(route,b.dataset.detail);b.onkeydown=e=>{if(e.key==='Enter')b.click();};});}
function modal(title,html,small=false){lastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${small?'small':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title">${esc(title)}</h2><button id="close-modal" class="icon-button ghost" aria-label="Fechar">${icon('close')}</button></div><div class="modal-body">${html}</div></section></div>`;$('#close-modal').onclick=closeModal;const overlay=$('.modal-overlay');overlay.onkeydown=e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'){const all=$$('button,input,select,textarea,a[href]',overlay).filter(x=>!x.disabled&&x.offsetParent!==null),first=all[0],last=all.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}};setTimeout(()=>$('input,select,textarea,button', $('.modal-body'))?.focus(),20);}
function closeModal(){$('#modal-root').innerHTML='';lastFocus?.focus();}
function field(f,v){const val=v??'',req=f.required?'required':'';if(f.type==='items')return '';let input='';if(f.type==='textarea')input=`<textarea name="${f.key}" ${req}>${esc(val)}</textarea>`;else if(f.type==='select')input=`<select name="${f.key}" ${req}>${f.options.map(x=>`<option value="${esc(x)}" ${x===val?'selected':''}>${esc(x)}</option>`).join('')}</select>`;else if(f.type==='relation'){const options=f.options==='users'?state.users.filter(u=>u.active):list(f.options);input=`<select name="${f.key}" ${req}><option value="">Selecionar…</option>${options.map(x=>`<option value="${x.id}" ${x.id===val?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`;}else input=`<input name="${f.key}" type="${f.type}" value="${esc(val)}" ${req} ${f.type==='number'?'min="0" step="0.01"':''}>`;return `<label class="${f.type==='textarea'?'wide':''}">${esc(f.label)}${f.required?' *':''}${input}</label>`;}
function editForm(e,r=null){const sc=SC[e],defaults={date:today(),installments:1,status:sc.fields.find(f=>f.key==='status')?.options[0],owner:session.user.id},data=r||defaults;let fields=sc.fields.map(f=>field(f,data[f.key])).join('');const hasItems=sc.fields.some(f=>f.type==='items');modal(`${r?'Editar':'Novo cadastro'} · ${sc.single}`,`<form id="record-form">${e==='sales'?'<div class="form-note">Ao salvar uma nova venda, o sistema cria as parcelas, o projeto e o briefing. Valores de vendas lançadas ficam preservados no histórico.</div>':''}${e==='subscriptions'?'<div class="form-note">A próxima conta a receber é gerada pelo botão “Gerar cobrança” no registro. O sistema não envia cobranças ao cliente.</div>':''}${['receivables','expenses'].includes(e)?'<div class="form-note">Registre pagamentos em “Abrir → Registrar pagamento”. Valores pagos não são alterados neste formulário.</div>':''}<div class="form-grid">${fields}${hasItems?'<div class="wide line-items"><h3>Serviços contratados</h3><div id="line-items"></div><button type="button" id="add-line">+ Adicionar serviço</button><div class="line-total" id="line-total"></div></div>':''}</div><div id="form-error"></div><div class="modal-footer"><button type="button" id="cancel-form">Cancelar</button><button type="submit" class="primary">Salvar ${sc.single}</button></div></form>`);$('#cancel-form').onclick=closeModal;
if(hasItems){(r?.items||[{}]).forEach(addItem);$('#add-line').onclick=()=>addItem({});$('[name=discount]').oninput=calcTotal;calcTotal();}
if(r&&['receivables','expenses'].includes(e)&&r.status!=='Cancelado')$('[name=status]').value='Pendente';
$('#record-form').onsubmit=async ev=>{ev.preventDefault();const button=$('button[type=submit]',ev.target);button.disabled=true;try{const values=Object.fromEntries(new FormData(ev.target));sc.fields.filter(f=>f.type==='number').forEach(f=>values[f.key]=Number(values[f.key]||0));if(hasItems)values.items=readItems();if(r){Object.assign(values,Object.fromEntries(Object.entries(r).filter(([key])=>!sc.fields.some(f=>f.key===key))));if(['receivables','expenses'].includes(e)&&values.status!=='Cancelado')values.status=r.status==='Cancelado'?'Pendente':r.status;}await api(`/records/${e}${r?'/'+r.id:''}`,r?'PUT':'POST',values);await reload();closeModal();render();toast('Cadastro salvo.');}catch(err){$('#form-error').innerHTML=`<div class="form-error">${esc(err.message)}</div>`;}finally{button.disabled=false;}};}
function addItem(item){const div=document.createElement('div');div.className='line-item';div.innerHTML=`<label>Serviço<select class="item-service" required><option value="">Selecionar…</option>${list('services').filter(s=>s.status==='Ativo'||s.id===item.service).map(s=>`<option value="${s.id}" ${s.id===item.service?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label>Quantidade<input class="item-qty" type="number" min="0.01" max="10000" step="0.01" value="${item.quantity||1}" required></label><label>Preço (R$)<input class="item-price" type="number" min="0" step="0.01" value="${item.price||0}" required></label><button type="button" class="remove-line" aria-label="Remover serviço">×</button>`;$('#line-items').append(div);$('.item-service',div).onchange=e=>{$('.item-price',div).value=list('services').find(s=>s.id===e.target.value)?.price||0;calcTotal();};$$('input',div).forEach(i=>i.oninput=calcTotal);$('.remove-line',div).onclick=()=>{div.remove();calcTotal();};calcTotal();}
function readItems(){return $$('.line-item').map(el=>({service:$('.item-service',el).value,quantity:Number($('.item-qty',el).value),price:Number($('.item-price',el).value)}));}
function calcTotal(){if($('#line-total'))$('#line-total').textContent='Total: '+money(readItems().reduce((s,i)=>s+i.quantity*i.price,0)-Number($('[name=discount]')?.value||0));}
async function mutateRecord(e,r,patch){try{await api('/records/'+e+'/'+r.id,'PUT',{...r,...patch});await reload();render();toast('Registro atualizado.');}catch(err){toast(err.message,true);render();}}
async function detail(e,id){const r=list(e).find(x=>x.id===id);if(!r)return;const sc=SC[e];modal(r.name,`<div class="details-grid">${sc.fields.filter(f=>!['items','checklist'].includes(f.type)&&f.key!=='checklist').map(f=>`<div class="${f.type==='textarea'?'wide':''}"><small>${esc(f.label)}</small><div class="detail-value">${f.type==='relation'?esc(lookup(f.options,r[f.key])):f.type==='date'?dateFmt(r[f.key]):f.type==='number'?number(r[f.key]):esc(r[f.key]||'—')}</div></div>`).join('')}</div>${r.items?`<div class="report-section"><h3>Serviços</h3>${r.items.map(i=>`<div class="mini-row"><strong>${esc(lookup('services',i.service))} × ${number(i.quantity)}</strong><span>${money(i.quantity*i.price)}</span></div>`).join('')}<div class="line-total">Total: ${money(r.amount)}</div></div>`:''}${r.checklist?`<div class="report-section"><h3>Checklist</h3><div class="checklist">${r.checklist.split('\n').filter(Boolean).map((line,i)=>`<label class="check-item ${/^\[x\]/i.test(line)?'done':''}"><input type="checkbox" data-check="${i}" ${/^\[x\]/i.test(line)?'checked':''}>${esc(line.replace(/^\[[ x]\]\s*/i,''))}</label>`).join('')}</div></div>`:''}${['receivables','expenses'].includes(e)?`<div class="report-section"><h3>Pagamentos</h3><p>Pago: ${money(r.paid)} · Saldo: ${money(r.amount-(r.paid||0))}</p>${(r.payments||[]).map(p=>`<div class="mini-row"><span>${dateFmt(p.date)} · ${esc(p.method)}</span><strong>${money(p.amount)}</strong></div>`).join('')}</div>`:''}${e==='campaigns'?`<div class="report-section"><h3>Indicadores calculados</h3><p>CPL: ${r.leads>0?money(r.spend/r.leads):'—'} · CPA: ${r.conversions>0?money(r.spend/r.conversions):'—'} · CTR: ${r.impressions>0?number(r.clicks/r.impressions*100)+'%':'—'} · ROAS: ${r.spend>0?number(r.revenue/r.spend)+'×':'—'}</p></div>`:''}${e==='clients'?clientHistory(id):''}<div class="attachments"><h3>Arquivos do registro</h3><div id="attachment-list"><small>Carregando anexos…</small></div><label>Anexar arquivo (até 3 MB)<input id="attachment-upload" type="file"></label></div><div class="modal-footer" style="flex-wrap:wrap"><button id="detail-delete" class="danger">Excluir</button>${['receivables','expenses'].includes(e)&&financialStatus(r)!=='Pago'&&r.status!=='Cancelado'?'<button id="settle" class="primary">Registrar pagamento</button>':''}${e==='proposals'?`<button id="print-proposal">Imprimir / PDF</button>${!r.sale?'<button id="convert" class="primary">Converter em venda</button>':''}`:''}${e==='contracts'?'<button id="print-contract">Imprimir / PDF</button>':''}${e==='subscriptions'?'<button id="generate" class="primary">Gerar cobrança</button>':''}${e==='expenses'&&r.recurring==='Mensal'&&!r.nextExpense?'<button id="generate-expense">Gerar próximo mês</button>':''}<button id="detail-edit">Editar</button></div>`);$('#detail-edit').onclick=()=>editForm(e,r);$('#detail-delete').onclick=()=>confirmModal('Excluir registro?',`Excluir “${r.name}”? Esta ação não pode ser desfeita.`,async()=>{await api(`/records/${e}/${id}`,'DELETE',{});await reload();closeModal();render();toast('Registro excluído.');});$('#settle')?.addEventListener('click',()=>settleForm(e,r));$('#convert')?.addEventListener('click',()=>confirmModal('Converter proposta em venda?','Serão criados uma venda, parcelas mensais, um projeto e um briefing. O primeiro vencimento será hoje.',()=>runAction(e,r,'convert',{due:today()})));$('#generate')?.addEventListener('click',()=>confirmModal('Gerar próxima cobrança?',`Será criada uma conta a receber de ${money(r.amount)}, com vencimento em ${dateFmt(r.nextDue)}.`,()=>runAction(e,r,'generate')));$('#generate-expense')?.addEventListener('click',()=>confirmModal('Gerar próxima despesa?','Será criada uma nova conta a pagar para o próximo mês, sem marcar como paga.',()=>runAction(e,r,'generate')));$('#print-proposal')?.addEventListener('click',()=>printDocument(e,r));$('#print-contract')?.addEventListener('click',()=>printDocument(e,r));$$('[data-check]').forEach(el=>el.onchange=async()=>{const lines=r.checklist.split('\n').filter(Boolean),i=Number(el.dataset.check);lines[i]=(el.checked?'[x] ':'[ ] ')+lines[i].replace(/^\[[ x]\]\s*/i,'');await mutateRecord(e,r,{checklist:lines.join('\n')});detail(e,id);});$('#attachment-upload').onchange=async ev=>{const file=ev.target.files[0];if(!file)return;if(file.size>3_000_000)return toast('O limite é 3 MB por arquivo.',true);try{const content=await fileBase64(file);await api('/attachments','POST',{record_id:id,name:file.name,content:content.split(',')[1]});toast('Arquivo anexado.');loadAttachments(id);}catch(err){toast(err.message,true);}};loadAttachments(id);}
function clientHistory(id){const rows=['sales','projects','receivables','tasks'].flatMap(e=>list(e).filter(r=>r.client===id).map(r=>({e,...r})));return `<div class="report-section"><h3>Histórico do cliente</h3>${rows.length?rows.map(r=>`<div class="mini-row"><div><strong>${esc(r.name)}</strong><small>${SC[r.e].title} · ${dateFmt(r.created)}</small></div>${badge(r.status)}</div>`).join(''):'<small>Sem movimentações vinculadas.</small>'}</div>`;}
async function loadAttachments(id){try{const files=await api('/attachments?record_id='+id);if($('#attachment-list'))$('#attachment-list').innerHTML=files.length?files.map(f=>`<a href="/api/attachments/${f.id}" download>${icon('file')} ${esc(f.name)} · ${number(f.size/1024)} KB</a>`).join(''):'<small>Nenhum arquivo anexado.</small>';}catch(err){toast(err.message,true);}}
function fileBase64(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});}
function confirmModal(t,desc,fn){modal(t,`<p>${esc(desc)}</p><div id="confirm-error"></div><div class="modal-footer"><button id="no">Voltar</button><button id="yes" class="primary">Confirmar</button></div>`,true);$('#no').onclick=closeModal;$('#yes').onclick=async()=>{$('#yes').disabled=true;try{await fn();}catch(e){$('#confirm-error').innerHTML=`<div class="form-error">${esc(e.message)}</div>`;if($('#yes'))$('#yes').disabled=false;}};}
async function runAction(e,r,action,b={}){await api(`/records/${e}/${r.id}/${action}`,'POST',{...b,version:r.version});await reload();closeModal();render();toast('Operação concluída.');}
function settleForm(e,r){modal('Registrar pagamento',`<form id="settle-form"><p>${esc(r.name)} · Saldo: ${money(r.amount-(r.paid||0))}</p><div class="form-grid">${field(F('amount','Valor pago (R$)','number',null,true),r.amount-(r.paid||0))}${field(F('date','Data do pagamento','date',null,true),today())}${field(F('method','Forma de pagamento','select',['Pix','Transferência','Boleto','Cartão','Dinheiro','Outro']),'Pix')}</div><div id="settle-error"></div><div class="modal-footer"><button class="primary">Confirmar pagamento</button></div></form>`,true);$('#settle-form').onsubmit=async ev=>{ev.preventDefault();const b=$('button',ev.target);b.disabled=true;try{await runAction(e,r,'settle',Object.fromEntries(new FormData(ev.target)));}catch(err){$('#settle-error').innerHTML=`<div class="form-error">${esc(err.message)}</div>`;b.disabled=false;}};}
function exportCSV(e,rows){const keys=['name',...new Set(rows.flatMap(r=>Object.keys(r)).filter(k=>!['name','items','payments','version','entity'].includes(k)))];const safe=v=>{const s=typeof v==='object'?JSON.stringify(v):String(v??'');return '"'+(/^[=+\-@\t\r]/.test(s)?"'"+s:s).replaceAll('"','""')+'"';};const csv='\uFEFF'+[keys.map(safe).join(';'),...rows.map(r=>keys.map(k=>safe(['client','owner','service','project'].includes(k)?lookup(({client:'clients',owner:'users',service:'services',project:'projects'})[k],r[k]):r[k])).join(';'))].join('\r\n');download(csv,`${e}-${today()}.csv`,'text/csv;charset=utf-8');}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function showRecovery(code){modal('Guarde o código de recuperação',`<p>Este código permite redefinir a senha. Guarde-o em um local seguro; ele é exibido apenas agora.</p><div class="recovery">${esc(code)}</div><div class="modal-footer"><button id="save-recovery">Baixar código</button><button id="saved" class="primary">Já guardei</button></div>`,true);$('#save-recovery').onclick=()=>download(`Prates Digital — código de recuperação\n${code}\nGuarde em local seguro.`, 'prates-codigo-recuperacao.txt','text/plain');$('#saved').onclick=closeModal;}
function printDocument(e,r){const s=state.settings,c=list('clients').find(x=>x.id===r.client)||{};printHTML(`<div class="print-brand">${s.logo?`<img src="${esc(s.logo)}" alt="Logo"> `:''}${esc(s.name)}</div><p>${esc(s.document)} · ${esc(s.email)} · ${esc(s.phone)}</p><h1>${e==='proposals'?'Proposta comercial':'Contrato'}: ${esc(r.name)}</h1><p>Cliente: <strong>${esc(c.name)}</strong> · ${esc(c.company||'')}<br>${esc(c.document||'')} · ${esc(c.email||'')}</p><p>Data: ${dateFmt(r.date||r.created)} ${r.validUntil?'· Válida até '+dateFmt(r.validUntil):''}</p>${r.items?`<table><thead><tr><th>Serviço</th><th>Quantidade</th><th>Preço unitário</th><th>Total</th></tr></thead><tbody>${r.items.map(i=>`<tr><td>${esc(lookup('services',i.service))}</td><td>${number(i.quantity)}</td><td>${money(i.price)}</td><td>${money(i.quantity*i.price)}</td></tr>`).join('')}</tbody></table><div class="print-total">Desconto: ${money(r.discount)}<br>Total: ${money(r.amount)}</div><p>Parcelamento: ${r.installments||1} parcela(s).</p>`:''}<h2>Condições</h2><div style="white-space:pre-wrap">${esc(r.terms||'Condições a definir.')}</div>${e==='contracts'?`<p>Vigência: ${dateFmt(r.start)} a ${dateFmt(r.end)}</p>`:''}<p style="margin-top:30px">${esc(s.proposalFooter||'')}</p>`);}
function printHTML(html){$('.print-area')?.remove();const area=document.createElement('div');area.className='print-area';area.innerHTML=html;document.body.append(area);window.print();}
function notifications(){const alerts=[...list('receivables').filter(r=>financialStatus(r)==='Atrasado').map(r=>({title:'Recebimento atrasado: '+r.name,e:'receivables',id:r.id})),...list('expenses').filter(r=>financialStatus(r)==='Atrasado').map(r=>({title:'Pagamento atrasado: '+r.name,e:'expenses',id:r.id})),...list('tasks').filter(r=>r.due&&r.due<=today()&&r.status!=='Concluída').map(r=>({title:'Tarefa: '+r.name,e:'tasks',id:r.id})),...list('projects').filter(r=>r.due&&r.due<=today()&&r.status!=='Finalizado').map(r=>({title:'Entrega: '+r.name,e:'projects',id:r.id})),...list('subscriptions').filter(r=>r.status==='Ativo'&&r.nextDue<=today()).map(r=>({title:'Mensalidade a gerar: '+r.name,e:'subscriptions',id:r.id}))];modal('Alertas da operação',alerts.length?`<div class="notification-list">${alerts.map((a,i)=>`<button data-alert="${i}">${icon('clock')}${esc(a.title)}</button>`).join('')}</div>`:empty('Tudo em dia','Nenhum vencimento ou prazo pendente para hoje.'));$$('[data-alert]').forEach(b=>b.onclick=()=>{const a=alerts[b.dataset.alert];detail(a.e,a.id);});}
function globalSearch(q){if(!q.trim())return;const results=Object.entries(state.data).flatMap(([e,rows])=>rows.filter(r=>JSON.stringify(r).toLowerCase().includes(q.toLowerCase())).map(r=>({e,r}))).slice(0,50);modal('Resultados da busca',results.length?`<div class="notification-list">${results.map((x,i)=>`<button data-result="${i}"><div>${esc(x.r.name)}<small style="display:block">${SC[x.e].title}</small></div></button>`).join('')}</div>`:empty('Nenhum resultado','Tente outro nome, contato ou descrição.'));$$('[data-result]').forEach(b=>b.onclick=()=>{const x=results[b.dataset.result];detail(x.e,x.r.id);});}
function reports(){const fin=financial(reportStart,reportEnd),sales=list('sales').filter(r=>r.status!=='Cancelado'&&inRange(r.date,reportStart,reportEnd));const mediaIn=sum(payments('receivables',reportStart,reportEnd,true).filter(r=>r.category==='Verba de mídia'),'amount'),mediaOut=sum(payments('expenses',reportStart,reportEnd,true).filter(r=>r.category==='Verba de mídia'),'amount');const props=list('proposals').filter(r=>inRange(r.date||r.created,reportStart,reportEnd));const byService={};sales.forEach(r=>(r.items||[]).forEach(i=>{const n=lookup('services',i.service);byService[n]=(byService[n]||0)+i.quantity*i.price;}));const byClient={};sales.forEach(r=>{const n=lookup('clients',r.client);byClient[n]=(byClient[n]||0)+r.amount;});const byOwner={};sales.forEach(r=>{const n=lookup('users',r.owner);byOwner[n]=(byOwner[n]||0)+r.amount;});const expensesBy={};payments('expenses',reportStart,reportEnd).forEach(p=>expensesBy[p.category]=(expensesBy[p.category]||0)+p.amount);const grouped=(data)=>Object.entries(data).length?`<table class="table"><tbody>${Object.entries(data).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${money(v)}</td></tr>`).join('')}</tbody></table>`:empty('Sem movimentações','Não há dados neste período.');$('#content').innerHTML=heading(title(),route==='balance'?'Resumo gerencial pelo regime de caixa, com vendas apresentadas separadamente.':'Entenda os resultados por cliente, serviço e responsável.',`<button id="print-report">${icon('file')} Imprimir / PDF</button><button id="csv-report">${icon('download')} Exportar vendas</button>`)+`<div class="report-filters"><label>De<input id="report-start" type="date" value="${reportStart}"></label><label>Até<input id="report-end" type="date" value="${reportEnd}"></label><button id="apply-report" class="primary">Aplicar período</button></div><div id="report-content"><div class="metrics">${metric('Recebimentos',money(fin.incoming),'Sem verba de mídia','wallet',true)}${metric('Despesas pagas',money(fin.outgoing),'Sem verba de mídia','wallet')}${metric('Resultado de caixa',money(fin.result),'Antes de aportes e retiradas','chart')}${metric('Vendas contratadas',money(sum(sales,'amount')),sales.length+' vendas no período','sales')}</div><section class="panel"><div class="panel-head"><h2>Demonstrativo gerencial</h2><small>${dateFmt(reportStart)} a ${dateFmt(reportEnd)}</small></div><table class="table"><tbody>${[['Recebimentos operacionais',fin.incoming],['Despesas operacionais pagas',-fin.outgoing],['Resultado operacional de caixa',fin.result],['Aportes dos sócios',fin.contributions],['Retiradas e reembolsos dos sócios',-fin.withdrawals],['Variação do caixa próprio no período',fin.net],['Verba de mídia recebida (separada)',mediaIn],['Verba de mídia paga (separada)',-mediaOut],['Variação total incluindo mídia',fin.net+mediaIn-mediaOut]].map(([k,v])=>`<tr><td>${k}</td><td>${money(v)}</td></tr>`).join('')}</tbody></table><div class="panel-body" style="padding-top:18px"><small>Variação do período; não representa saldo bancário conciliado nem balanço patrimonial contábil. Reembolsos registrados em Sócios não devem ser duplicados em Despesas.</small></div></section>${route==='reports'?`<div class="grid-main report-section"><section class="panel"><div class="panel-head"><h2>Vendas por cliente</h2></div>${grouped(byClient)}</section><section class="panel"><div class="panel-head"><h2>Vendas por responsável</h2></div>${grouped(byOwner)}</section></div><div class="grid-main"><section class="panel"><div class="panel-head"><div><h2>Serviços vendidos</h2><small>Valores brutos, antes do desconto da venda</small></div></div>${grouped(byService)}</section><section class="panel"><div class="panel-head"><h2>Despesas por categoria</h2></div>${grouped(expensesBy)}</section></div><div class="metrics">${metric('Propostas aprovadas',props.length?number(props.filter(r=>r.status==='Aprovada').length/props.length*100)+'%':'—',props.length+' propostas no período','file')}${metric('Contas em atraso',list('receivables').filter(r=>financialStatus(r)==='Atrasado').length,'Situação atual · todos os períodos','clock')}${metric('Clientes cadastrados',list('clients').filter(r=>inRange(r.created,reportStart,reportEnd)).length,'Novos no período','clients')}${metric('Projetos finalizados',list('projects').filter(r=>r.status==='Finalizado'&&inRange(r.updated,reportStart,reportEnd)).length,'Pela última atualização','project')}</div>`:''}</div>`;$('#apply-report').onclick=()=>{const a=$('#report-start').value,b=$('#report-end').value;if(!a||!b||a>b)return toast('Selecione um período válido.',true);reportStart=a;reportEnd=b;reports();};$('#csv-report').onclick=()=>exportCSV('sales',sales);$('#print-report').onclick=()=>printHTML(`<div class="print-brand">${esc(state.settings.name)}</div><h1>${esc(title())}</h1><p>${dateFmt(reportStart)} a ${dateFmt(reportEnd)}</p>`+$('#report-content').innerHTML);}
function usersPage(){$('#content').innerHTML=heading('Equipe e acessos','Contas individuais, responsáveis e permissões de cada área.',`<button class="primary" id="new-user">${icon('plus')} Adicionar pessoa</button>`)+`<section class="panel"><table class="table"><thead><tr><th>Nome</th><th>E-mail</th><th>Perfil</th><th>Situação</th><th>Ações</th></tr></thead><tbody>${state.users.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td>${roleLabel[u.role]}</td><td>${badge(u.active?'Ativo':'Inativo')}</td><td><button data-user="${u.id}">Permissões</button></td></tr>`).join('')}</tbody></table></section><div class="form-note" style="margin-top:20px">Administrador: todas as áreas. Financeiro: clientes, serviços, contratos, vendas, financeiro, metas e tarefas. Comercial: clientes, funil, serviços, propostas, contratos, vendas, metas e tarefas. Produção: clientes, serviços, briefings, projetos, conteúdo, campanhas e tarefas. Os perfis permitidos podem editar os registros das respectivas áreas.</div>`;$('#new-user').onclick=()=>{modal('Adicionar pessoa',`<form id="user-form"><div class="form-grid">${field(F('name','Nome','text',null,true),'')}${field(F('email','E-mail','email',null,true),'')}${field(F('password','Senha inicial (mínimo 10 caracteres)','password',null,true),'')}<label>Perfil<select name="role">${Object.entries(roleLabel).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label></div><div id="user-error"></div><div class="modal-footer"><button class="primary">Criar acesso</button></div></form>`);$('#user-form').onsubmit=async e=>{e.preventDefault();const btn=$('button',e.target);btn.disabled=true;try{const r=await api('/users','POST',Object.fromEntries(new FormData(e.target)));await reload();usersPage();showRecovery(r.recovery);}catch(err){$('#user-error').innerHTML=`<div class="form-error">${esc(err.message)}</div>`;btn.disabled=false;}};};$$('[data-user]').forEach(b=>b.onclick=()=>{const u=state.users.find(x=>x.id===b.dataset.user);modal('Permissões de '+u.name,`<form id="permissions-form"><label>Perfil<select name="role">${Object.entries(roleLabel).map(([k,v])=>`<option value="${k}" ${u.role===k?'selected':''}>${v}</option>`).join('')}</select></label><label style="margin-top:18px"><input type="checkbox" name="active" ${u.active?'checked':''}> Acesso ativo</label><div id="permission-error"></div><div class="modal-footer"><button class="primary">Salvar permissões</button></div></form>`,true);$('#permissions-form').onsubmit=async ev=>{ev.preventDefault();try{await api('/users/'+u.id,'PUT',{role:$('[name=role]').value,active:$('[name=active]').checked});await reload();closeModal();usersPage();toast('Permissões atualizadas.');}catch(err){$('#permission-error').innerHTML=`<div class="form-error">${esc(err.message)}</div>`;}};});}
async function auditPage(){$('#content').innerHTML=heading('Histórico de alterações','Criações, alterações e operações importantes ficam registradas.')+'<p>Carregando histórico…</p>';try{const rows=await api('/audit');if(route!=='audit')return;$('#content').innerHTML=heading('Histórico de alterações','Últimos 500 eventos. Abra uma alteração para consultar a versão anterior.')+`<section class="panel table-wrap"><table class="table"><thead><tr><th>Quando</th><th>Pessoa</th><th>Ação</th><th>Área</th><th>Detalhes</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${esc(r.at.replace('T',' '))}</td><td>${esc(r.actor||'Sistema')}</td><td>${esc(r.action)}</td><td>${esc(SC[r.entity]?.title||r.entity||'Acesso')}</td><td><button data-audit="${i}">Ver alteração</button></td></tr>`).join('')}</tbody></table></section>`;$$('[data-audit]').forEach(b=>b.onclick=()=>{const r=rows[b.dataset.audit],d=JSON.parse(r.detail);modal('Detalhes da alteração',`<p>${esc(r.action)} · ${esc(r.actor)}</p><pre style="white-space:pre-wrap;font-size:12px;overflow-wrap:anywhere">${esc(JSON.stringify(d,null,2))}</pre>`);});}catch(err){toast(err.message,true);}}
function settingsPage(){const s=state.settings;$('#content').innerHTML=heading('Configurações','Identidade da empresa, documentos e cópia de segurança.')+`<section class="panel settings-box"><div class="panel-head"><h2>Dados da Prates Digital</h2></div><div class="panel-body"><form id="settings-form"><div class="form-grid">${[F('name','Nome da empresa','text',null,true),F('document','CNPJ (quando disponível)'),F('email','E-mail','email'),F('phone','Telefone'),F('address','Endereço'),F('proposalFooter','Rodapé das propostas','textarea')].map(f=>field(f,s[f.key])).join('')}<label class="wide">Logo PNG, JPG ou WebP (até 1 MB)<input id="logo-upload" type="file" accept="image/png,image/jpeg,image/webp"></label></div><div class="modal-footer"><button class="primary">Salvar configurações</button></div></form></div></section><section class="panel settings-box report-section"><div class="panel-head"><h2>Backup completo</h2></div><div class="panel-body"><p>Baixe o banco de dados e os anexos. O arquivo contém informações privadas da empresa e hashes de acesso; guarde-o em local seguro.</p><a href="/api/backup" download><button>${icon('download')} Baixar backup ZIP</button></a><p style="margin-top:18px;font-size:12px">Na versão online, use também os backups do provedor PostgreSQL. O guia explica exportação, migração e restauração.</p></div></section>`;$('#settings-form').onsubmit=async e=>{e.preventDefault();const btn=$('button',e.target);btn.disabled=true;try{const data=Object.fromEntries(new FormData(e.target));data.logo=s.logo||'';const f=$('#logo-upload').files[0];if(f){if(f.size>1_000_000)throw Error('A logo deve ter no máximo 1 MB.');data.logo=await fileBase64(f);}await api('/settings','PUT',data);await reload();shell();toast('Configurações salvas.');}catch(err){toast(err.message,true);}finally{btn.disabled=false;}};}
boot();
